//
// this is a more geometrically correct version of https://www.shadertoy.com/view/43yyzt
//

#define T 6.283
#define P(x) vec2(cos(x),sin(x))
//#define U(r) round(r * T * (1.0 + 0.08*sin(13.*sin(r-1.))))
#define U(r) round(r * T * (1.0 + 0.1*mod(r,2.)))
#define H(x) 37.*sin((16.+x)*(iTime*0.0003+3.))
// polar with vec2(r, phi/T)
vec4 closest_points(vec2 polar, out vec2 phi, out float U) {
    float r = round(polar.x);
    U = U(r);
    float s = fract(H(r)+0.5)-0.5;
    phi.x = polar.y * U + s;
    phi = vec2(floor(phi.x), ceil(phi.x)) - s;
    phi /= U+1e-20;
    vec2 a = P(phi.x*T)*r;
    vec2 b = P(phi.y*T)*r;
    return vec4(a, b);
}
float edge(vec2 p, vec2 x0, vec2 x1) {
    vec2 rp=p-x0,d=x1-x0;
    return length(rp-d*clamp(dot(rp,d)/dot(d,d),0.,1.));
}
bool decide(float phi1, float phi2, float U) {
    float t = fract(iTime*0.8-U*0.01)*5.,sel=mod(iTime*0.2,3.),m;
    if (sel < 0.3)
        m = .5;
    else if (sel < 1.8)
        m = 0.3+0.2*sin(t);
    else
        m = 0.3+0.4*sin(t+(phi1+phi2)*T*.5);
    return abs(phi1 - phi2)*U < m;
}
float disk_graph(vec2 pos) {
    vec2 polar = vec2(length(pos), atan(pos.y, pos.x) / T);
    float s = sign(polar.x - round(polar.x));
    vec2 phi_b = vec2(0);
    vec2 phi_c = vec2(0);
    vec2 U2 = vec2(0);
    vec4 b = closest_points(polar,phi_b,U2.x);
    vec4 c = closest_points(polar+vec2(s,0),phi_c,U2.y);
    float U = max(U2.x, U2.y); // min gives a different, but also interesting look
    float v = min(distance(pos, b.xy), distance(pos, b.zw));
    v = min(v, min(distance(pos, c.xy), distance(pos, c.zw)));
    // now decide which connects to which
    if (decide(phi_b.x, phi_c.x, U))
        v = min(v, edge(pos, b.xy, c.xy));
    if (decide(phi_b.y, phi_c.y, U))
        v = min(v, edge(pos, b.zw, c.zw));
    if (decide(phi_b.x, phi_c.y, U))
        v = min(v, edge(pos, b.xy, c.zw));
    if (decide(phi_b.y, phi_c.x, U))
        v = min(v, edge(pos, b.zw, c.xy));
    return v;
}


float disk_dots(vec2 pos) {
    float r = length(pos);
    vec2 rf = vec2(floor(r), ceil(r));
    vec2 U = U(rf);
    vec2 phi = atan(pos.y, pos.x) / T * U;
    vec2 dphi = fract(phi+H(rf));
    dphi -= round(dphi);
    float dr = fract(r);
    float inner = length(vec2(dr, dphi.x));
    float outer = length(vec2(dr-1., dphi.y));
    return min(inner,outer);
}

void mainImage( out vec4 fragColor, in vec2 fragCoord ) {
    vec2 uv = (fragCoord - iResolution.xy*0.5)/24.;
    float d = disk_graph(uv);
    float a = smoothstep(.2,0.,d);
    float b = smoothstep(-.9,-.98, cos(10.*disk_dots(uv)));
    fragColor = vec4(mix(vec3(0.,.3,1.)*b + .1+.1*cos(d*45.), vec3(.5,.8,1), a*3.), 1.0);
}
